import { chromium } from '@playwright/test'
import { loadE2eEnv } from './e2e/fixtures/env-loader.js'
import { loginWithRealAccount, waitForRoutesReady, collectAppRoutes, pickMenuRoute } from './e2e/fixtures/auth-helpers.js'

loadE2eEnv()

const baseURL = process.env.E2E_BASE_URL || 'http://127.0.0.1:8098'

const browser = await chromium.launch({ headless: true })
const context = await browser.newContext({ baseURL, viewport: { width: 1600, height: 900 } })
const page = await context.newPage()

const logs = []
page.on('console', (m) => logs.push(`[${m.type()}] ${m.text()}`))

try {
  console.log('login...')
  await loginWithRealAccount(page)
  await waitForRoutesReady(page)
  await page.waitForTimeout(1500)

  const routes = await collectAppRoutes(page)
  const target = routes.filter((r) => String(r.filePath || '').includes('supervision/agreement/version'))
  console.log('matched routes:', JSON.stringify(target, null, 2))

  const listPath = target.find((r) => String(r.filePath).includes('/index'))?.path
  if (!listPath) throw new Error('list route not found')
  console.log('goto list:', listPath)
  await page.goto(`${baseURL}/#${listPath}`)
  await page.waitForTimeout(2500)
  await page.screenshot({ path: 'verify-list.png', fullPage: true })

  // find first 修改/edit button in list
  const editBtn = page.locator('button:has-text("修改"), a:has-text("修改"), .el-button:has-text("修改")').first()
  const cnt = await editBtn.count()
  console.log('edit button count:', cnt)
  if (cnt === 0) {
    // maybe view button
    const viewBtn = page.locator('button:has-text("编辑"), a:has-text("编辑")').first()
    console.log('view/edit btn count:', await viewBtn.count())
    if (await viewBtn.count()) { await viewBtn.click() }
  } else {
    await editBtn.click()
  }
  await page.waitForTimeout(2500)
  await page.screenshot({ path: 'verify-edit.png', fullPage: true })

  // Read the 控制百分比 input value
  const rationInput = page.locator('.el-form-item:has-text("控制百分比") input').first()
  const val = await rationInput.inputValue().catch(() => '(not found)')
  console.log('控制百分比 input value =', val)
  console.log('URL now:', page.url())
} catch (e) {
  console.error('ERROR:', e.message)
  await page.screenshot({ path: 'verify-error.png', fullPage: true }).catch(() => {})
} finally {
  await browser.close()
}

