const baseURL = process.env.E2E_BASE_URL || 'http://127.0.0.1:8098'
const API_HOST = 'http://unlimited.g.h5.admin.web.v3.fangdichan.shiqu.suzhou.dev.zhi.com'

const browser = await chromium.launch({ headless: true })
const context = await browser.newContext({ baseURL, viewport: { width: 1600, height: 900 } })
const page = await context.newPage()

// Rewrite /api/v3.0/** -> dev host /v3.0/** (nginx would 502 since local gateway down)
await context.route('**/api/v3.0/**', async (route) => {
  const req = route.request()
  const url = new URL(req.url())
  const target = API_HOST + url.pathname.replace('/api/v3.0', '/v3.0') + url.search
  try {
    const resp = await context.request.fetch(target, {
      method: req.method(),
      headers: req.headers(),
      data: req.postData() || undefined
    })
    const headers = resp.headers()
    await route.fulfill({ status: resp.status(), headers, body: await resp.body() })
  } catch (e) {
    await route.abort()
  }
})

